import collections

def task_func(csv_file, emp_prefix='EMP$$'):
    emp_count = collections.defaultdict(int)
    with open(csv_file, mode='r', newline='') as file:
        reader = csv.reader(file)
        for row in reader:
            emp_id = row[0]  # Assuming the employee ID is in the first column
            if emp_id.startswith(emp_prefix):
                emp_count[emp_id] += 1
    return dict(emp_count)

