import json
from glob import glob

def task_func(directory, string):
    # Find all JSON files in the directory and its subdirectories
    json_files = glob(f"{directory}/**/*.json", recursive=True)

    # Initialize a list to store the paths of files containing the string
    result = []

    # Iterate over each JSON file
    for json_file in json_files:
        try:
            # Open the JSON file and load its content
            with open(json_file, 'r') as file:
                data = json.load(file)

                # Recursively search for the string within the JSON data structure
                if search_string(data, string):
                    result.append(json_file)
        except json.JSONDecodeError:
            # Skip files that are not valid JSON
            continue

    return result

def search_string(data, target):
    # Base case: if the data is a string, check if it contains the target
    if isinstance(data, str) and target in data:
        return True

    # If the data is a list or dictionary, recursively search each element
    if isinstance(data, (list, dict)):
        for item in data:
            if search_string(item, target):
                return True

    return False

